import{_ as t,o as h,c as o,a3 as i}from"./chunks/framework.DX_KL3e0.js";const a="/help/screenshots/quan-tri/nguoi-dung.png",m=JSON.parse('{"title":"Người dùng & phân quyền","description":"","frontmatter":{},"headers":[],"relativePath":"quan-tri/nguoi-dung.md","filePath":"quan-tri/nguoi-dung.md","lastUpdated":1781595364000}'),g={name:"quan-tri/nguoi-dung.md"};function r(s,n,c,u,e,l){return h(),o("div",null,[...n[0]||(n[0]=[i('<h1 id="nguoi-dung-phan-quyen" tabindex="-1">Người dùng &amp; phân quyền <a class="header-anchor" href="#nguoi-dung-phan-quyen" aria-label="Permalink to &quot;Người dùng &amp; phân quyền&quot;">​</a></h1><p>Module <strong>Người Dùng</strong> giúp quản trị viên tạo, sửa, gán vai trò và <strong>phân quyền chi tiết theo module</strong> cho từng tài khoản.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/users</code> (nhóm <em>Quản Trị</em>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin. Quản lý chỉ <code>Xem</code>.</li><li><strong>Phân quyền 2 tầng:</strong> vai trò quyết định mặc định + tinh chỉnh chi tiết cho từng người.</li></ul></div><h2 id="giao-dien-danh-sach" tabindex="-1">Giao diện danh sách <a class="header-anchor" href="#giao-dien-danh-sach" aria-label="Permalink to &quot;Giao diện danh sách&quot;">​</a></h2><p><img src="'+a+'" alt="Trang Quản lý Người dùng"></p><h2 id="tao-sua-nguoi-dung" tabindex="-1">Tạo / sửa người dùng <a class="header-anchor" href="#tao-sua-nguoi-dung" aria-label="Permalink to &quot;Tạo / sửa người dùng&quot;">​</a></h2><p>Nhấn <strong>Thêm người dùng</strong> (hoặc bấm vào một người để sửa). Cửa sổ chia thành <strong>5 tab</strong>:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>📝 Thông Tin</strong></td><td>Họ tên, email, số điện thoại, vai trò, công ty, phòng ban, bộ phận, chức vụ, quản lý trực tiếp, thẻ tags, trạng thái. Khi <em>tạo mới</em> có thêm trường mật khẩu.</td></tr><tr><td><strong>🗂️ Hồ Sơ Nhân Sự</strong></td><td>Thông tin cá nhân, mã nhân viên, ngày vào làm, ngân hàng, liên hệ khẩn cấp...</td></tr><tr><td><strong>💰 Chế Độ &amp; Đãi Ngộ</strong></td><td>Phụ cấp ăn ca/gửi xe/đi lại, bảo hiểm xã hội, đơn vị trả lương.</td></tr><tr><td><strong>🔐 Phân Quyền</strong></td><td>Ma trận quyền chi tiết theo module (xem bên dưới).</td></tr><tr><td><strong>🔑 Đổi Mật Khẩu</strong></td><td>Đặt lại mật khẩu cho người dùng (chỉ khi sửa).</td></tr></tbody></table><h3 id="cac-buoc-tao-nhanh" tabindex="-1">Các bước tạo nhanh <a class="header-anchor" href="#cac-buoc-tao-nhanh" aria-label="Permalink to &quot;Các bước tạo nhanh&quot;">​</a></h3><ol><li>Mở tab <strong>Thông Tin</strong>, nhập <strong>Họ tên</strong> và <strong>Email</strong> (bắt buộc).</li><li>Chọn <strong>Vai trò</strong> — hệ thống tự gán bộ quyền mặc định tương ứng.</li><li>Chọn <strong>Công ty → Phòng ban → Bộ phận → Chức vụ</strong> (lọc theo nhau).</li><li>Đặt <strong>Mật khẩu</strong> (≥ 8 ký tự, có chữ và số).</li><li>(Tuỳ chọn) Mở tab <strong>Phân Quyền</strong> để tinh chỉnh.</li><li>Nhấn <strong>Lưu</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Vai trò Super Admin</p><p>Chỉ Super Admin mới gán được vai trò <strong>Super Admin</strong> cho người khác.</p></div><h2 id="phan-quyen-chi-tiet-tab-🔐-phan-quyen" tabindex="-1">Phân quyền chi tiết (tab 🔐 Phân Quyền) <a class="header-anchor" href="#phan-quyen-chi-tiet-tab-🔐-phan-quyen" aria-label="Permalink to &quot;Phân quyền chi tiết (tab 🔐 Phân Quyền)&quot;">​</a></h2><p>Tab này hiển thị <strong>ma trận module × hành động</strong>. Mỗi ô bật/tắt một quyền cho từng module (và module con thụt cấp). 7 hành động: <strong>Xem, Thêm, Sửa, Xóa, Duyệt, Xuất, Nhận thông báo</strong>.</p><p>Công cụ hỗ trợ:</p><ul><li><strong>Quyền mẫu (preset):</strong> áp dụng nhanh bộ quyền có sẵn (Toàn quyền, Quản trị, Quản lý, Nhân viên) hoặc mẫu tùy chỉnh. Có thể <strong>Lưu mẫu</strong> từ lựa chọn hiện tại, <strong>Sửa/Xóa</strong> mẫu, hoặc <strong>Khôi phục mẫu gốc</strong>.</li><li><strong>Sao chép từ người khác:</strong> sao toàn bộ quyền của một người dùng đã có.</li><li><strong>Bật/tắt theo cột:</strong> bấm tên hành động ở đầu cột để bật/tắt cho mọi module.</li><li><strong>Xóa hết:</strong> bỏ toàn bộ quyền.</li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Ma trận phân quyền chi tiết với các nút quyền mẫu. <em>(Ảnh sẽ được bổ sung.)</em></p></div><div class="warning custom-block"><p class="custom-block-title">Kế thừa quyền module con</p><p>Module con (ví dụ các phân hệ trong Quản lý Tài sản, Chấm công) <strong>kế thừa quyền module mẹ</strong> nếu chưa cấu hình riêng — tránh khóa nhầm người dùng cũ khi hệ thống thêm phân hệ mới.</p></div><h2 id="đoi-mat-khau-trang-thai" tabindex="-1">Đổi mật khẩu &amp; trạng thái <a class="header-anchor" href="#đoi-mat-khau-trang-thai" aria-label="Permalink to &quot;Đổi mật khẩu &amp; trạng thái&quot;">​</a></h2><ul><li><strong>Đổi mật khẩu:</strong> tab <strong>🔑 Đổi Mật Khẩu</strong> — nhập mật khẩu mới (≥ 8 ký tự, có chữ và số) rồi lưu.</li><li><strong>Trạng thái:</strong> trường <em>Trạng thái</em> ở tab Thông Tin — <code>Đang hoạt động</code> / <code>Không hoạt động</code>. Tài khoản không hoạt động không đăng nhập được.</li></ul><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a> · <a href="/help/quan-tri/co-cau-to-chuc.html">Cơ cấu tổ chức</a></p>',21)])])}const p=t(g,[["render",r]]);export{m as __pageData,p as default};
